import{_ as s,l as o,o as e,c as l,v as r,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"VLIW 与 EPIC","description":"","frontmatter":{"title":"VLIW 与 EPIC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vliw-epic.md","filePath":"cs/vliw-epic.md","lastUpdated":1789023840000}'),h={name:"cs/vliw-epic.md"};function E(I,a,u,m,P,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="vliw-与-epic" tabindex="-1">VLIW 与 EPIC <a class="header-anchor" href="#vliw-与-epic" aria-label="Permalink to &quot;VLIW 与 EPIC&quot;">​</a></h1><div class="epigraph"><p>超标量用硬件在运行时找独立指令；VLIW 让编译器把能同拍执行的操作打进一个长字，硬件按槽直发，不再做复杂唤醒。</p><footer>—— 据 Fisher, Very Long Instruction Word architectures；Itanium / EPIC 的公开叙述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/flynn-taxonomy">上一课</a> 把多发射仍标成 SISD 上的 ILP。<a href="/cs/issue-queue-wakeup">发射队列</a> 的唤醒/选择限制频率。本课不重画 Flynn 格。缺口是 <strong>VLIW：并行性在编译时打包；EPIC 用谓词与投机 load 补上「编译看不见的」那部分。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宽发射核的 IQ 与 <a href="/cs/prf-free-list">PRF</a> 很贵。若编译器已经用追踪调度把独立操作排好，硬件可以按「槽 0 ALU、槽 1 访存、槽 2 分支」直送，省掉运行时唤醒。缺口不是 SIMD 的数据并行，而是<strong>指令级并行的静态化</strong>。失败模式：二进制绑死机器宽度，cache miss 让整束停顿。</p><p><span class="marginnote">Fisher 的 VLIW 来自微码宽字。Itanium 的 EPIC 加谓词执行、投机 load 与恢复，试图在通用代码上接近 VLIW 而不完全暴露槽。商业上通用负载让位于乱序核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器把最多 \\(W\\) 个操作打进 bundle，标明停顿或停顿组。硬件按 bundle 取指，译码几乎一对一到功能单元。谓词：两条方向都编码，用条件寄存器作废其中一路，少用 <a href="/cs/gshare-predictor">gshare</a>。投机 load：提前 load，若异常则推迟到使用点。</p>',8)),(e(),n(p,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E6%89%93%E5%8C%85%22%5D%20--%3E%20BUNDLE%5B%22VLIW%20%E6%9D%9F%22%5D%0A%20%20BUNDLE%20--%3E%20SLOTS%5B%22%E6%8C%89%E6%A7%BD%E7%9B%B4%E5%8F%91%22%5D%0A%20%20MISS%5B%22%E4%B8%80%E6%A7%BD%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20STALL%5B%22%E6%95%B4%E6%9D%9F%E6%88%96%E5%90%8E%E7%BB%AD%E6%9D%9F%E5%81%9C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与乱序对照：ILP 窗口从 ROB 挪到编译器的追踪。对象代码随微结构宽度失效，这与 <a href="/cs/isa-abi-boundary">ISA 作为 ABI</a> 的「二进制稳定」紧张——EPIC 想用一层抽象缓解，仍难。DSP 与某些加速器至今用 VLIW，因为代码可控、缺失可预测。</p><p>不要把这里写成 Transformer 的静态图编译；那是大模型栏。本课只谈 CPU/DSP 指令束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评价 Itanium 生态。下一课数据流与解耦访存：另一条「让编译器/硬件把访存与运算拆开」的路，不是长指令字。向量 lane 是 SIMD 格子，不是 VLIW 槽。</p><p>后课默认：静态打包省 IQ，但把 miss 与二进制兼容变成编译问题。把 load 与使用解耦到不同时钟域/队列，是 DAE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VLIW 把 ILP 打包交给编译器，硬件按槽发射。</li><li>EPIC 用谓词与投机 load 补通用代码；通用 CPU 仍回到乱序。</li><li>解耦访存执行是下一课另一条静态/硬件混合路。</li><li>出处：Fisher；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const C=s(h,[["render",E]]);export{A as __pageData,C as default};
